sheet.css:
#sketchpad-controls { line-height: 1; width: 404px; display: flex; justify-content: space-between; flex-wrap: wrap; margin: auto; }
#sketchpad-color-palette { display: inline-block; text-align: left; flex-grow: 1; }
.sketchpad-color-select { cursor: pointer; height: 33px; width: 33px; border-radius: 4px; padding: 0px; border: 1px solid rgb(204, 204, 204); }
#sketchpad-actions { display: inline-block; text-align: right; flex-grow: 1; }
#sketchpad-actions button { margin-left: 4px; }
#sketchpad-canvas { touch-action: none; border: 2px solid rgb(170, 170, 170); }
.sketchpad-circle { border-radius: 250px; }
#countdown-timer { width: 404px; text-align: right; font-size: 12px; margin-bottom: 0.2em; }

children.text:
.jspsych-survey-multi-choice-question { margin-top: 2em; margin-bottom: 2em; text-align: left; }
.jspsych-survey-multi-choice-text span.required {color: darkred;}
.jspsych-survey-multi-choice-horizontal .jspsych-survey-multi-choice-text {  text-align: center;}
.jspsych-survey-multi-choice-option { line-height: 2; }
.jspsych-survey-multi-choice-horizontal .jspsych-survey-multi-choice-option {  display: inline-block;  margin-left: 1em;  margin-right: 1em;  vertical-align: top;}
label.jspsych-survey-multi-choice-text input[type='radio'] {margin-right: 1em;}
